import {loadWorkspace, saveWorkspace, logout} from './cloud.js';
import {openMercadoLivre} from './mercado-livre.js';
import {showAccess} from './access.js';
import {channels,available,round,quote,priceFor,economics,addOrder,transition,totals,columns,parseCSV,importProduct,issues} from './domain.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n);
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',catalog:'M3 7l9-4 9 4-9 4z M3 7v10l9 4 9-4V7 M12 11v10',stock:'M3 21V8l9-5 9 5v13 M7 21v-9h10v9 M7 16h10',orders:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 8h6 M9 12h6',finance:'M3 20h18 M6 16V9 M12 16V4 M18 16v-6',pricing:'M4 4h16v16H4z M8 8h8 M8 12h1 M15 12h1 M8 16h1 M15 16h1',bulk:'M12 16V3 M7 8l5-5 5 5 M4 13v7h16v-7',channels:'M8 8l8 8 M16 8l-8 8 M3 3h5v5H3z M16 3h5v5h-5z M3 16h5v5H3z M16 16h5v5h-5z',plan:'M5 4v16 M5 5h14l-3 4 3 4H5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',bell:'M6 17h12l-2-4V9a4 4 0 0 0-8 0v4z M10 20h4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',check:'M4 12l5 5L20 6',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',close:'M5 5l14 14 M5 19L19 5',menu:'M4 6h16 M4 12h16 M4 18h16'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.catalog}"/></svg>`;
const measures=[{tamanho:'P',altura:72,largura:56,manga:22},{tamanho:'M',altura:72,largura:57,manga:23},{tamanho:'G',altura:75,largura:60,manga:24},{tamanho:'GG',altura:77,largura:63,manga:25}];
function seed(){const s={products:['Built to Last','Essential','Faith over Fear','Urban Motion'].map((name,i)=>({id:'p'+i,name,title:'Camiseta '+name,sku:['BTL-PT-M','ESS-BR-G','FAI-OF-P','URB-PT-GG'][i],color:['Preta','Branca','Off-white','Preta'][i],size:['M','G','P','GG'][i],cost:25+i,price:69.9+i*5,stock:[80,64,28,8][i],reserved:0,safety:5,group:name,images:[],measures:structuredClone(measures),categories:{},brand:'',description:'',channelPrices:{}})),orders:[],rules:Object.fromEntries(channels.map((c,i)=>[c,{fee:[16,18,15,16][i],fixed:6,freight:5,tax:6,margin:25,programFee:0,subsidy:0,fulfillment:0,program:'Manual · exemplo'}])),nextOrder:1,theme:'dark',notices:[],queued:[],version:4};for(let i=0;i<5;i++){const o=addOrder(s,'p'+i%3,channels[i%4],i%2+1);o.date=new Date(Date.now()-i*86400000).toISOString();if(i>1)transition(s,o.id,'Enviado');}return s;}
function emptyWorkspace() {
  const demo = seed();
  return {...demo, products: [], orders: [], nextOrder: 1, notices: [], queued: []};
}
let state = emptyWorkspace();
let revision = 0;
let authenticated = false;
let saving = false;
let page='overview',period=7,filter='',draftRules=structuredClone(state.rules),selected=state.products[0]?.id,imported=[],importErrors=[],importName='',installPrompt;
async function persist() {
  if (!authenticated || saving) throw new Error('Aguarde a gravação atual.');
  saving = true;
  const app = $('#app');
  const dialog = $('#modal');
  app.inert = true;
  dialog.inert = true;
  try {
    const {theme, ...shared} = state;
    revision = await saveWorkspace(shared, revision);
  } finally {
    saving = false;
    app.inert = false;
    dialog.inert = false;
  }
}
function saveTheme(){localStorage.setItem('centralwork-theme',state.theme);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3500);}function notice(s){state.notices.unshift({text:s,date:new Date().toISOString()});state.notices=state.notices.slice(0,60);}function theme(){document.documentElement.dataset.theme=state.theme==='system'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):state.theme;}
const nav=[['overview','Visão geral'],['catalog','Produtos'],['stock','Estoque'],['orders','Pedidos'],['finance','Financeiro'],['pricing','Precificação'],['bulk','Importação em massa'],['channels','Canais de venda'],['plan','Plano de evolução'],['settings','Configurações']];
const button=(text,action,primary=false,ico='plus')=>`<button class="btn ${primary?'primary':''}" data-action="${action}">${icon(ico)}${text}</button>`;
function shell(){theme();$('#app').innerHTML=`<aside><a class="brand" href="#" data-page="overview"><span class="brand-mark">CW<span></span></span><div>Central<span>Work</span><small>OPERATION CENTER</small></div></a><div class="workspace"><span class="avatar">W</span><div>Work Têxtil<small>Operação da equipe</small></div><span class="dot"></span></div><p class="nav-caption">WORKSPACE</p><nav>${nav.map(([id,n])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(id)}${n}${id==='orders'?`<span class="count">${state.orders.filter(o=>o.status==='Reservado').length}</span>`:''}</button>`).join('')}</nav><div class="aside-bottom"><span class="pulse"></span> Dados compartilhados no Supabase<small>CentralWork / versão interativa 1.0</small></div></aside><div class="main"><header><button class="icon-btn mobile" data-action="menu" aria-label="Abrir menu">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <strong>${nav.find(n=>n[0]===page)?.[1]}</strong></div><div class="header-actions"><span class="demo"><span class="dot"></span> ÁREA RESTRITA</span><button class="icon-btn" data-action="theme" aria-label="Alternar tema">${icon('moon')}</button><button class="icon-btn" data-action="notices" aria-label="Notificações">${icon('bell')}<i>${state.notices.length}</i></button><span class="avatar">WT</span></div></header><main id="content"></main><footer>CentralWork <span>Uma operação. Todos os canais.</span><small>APIs ainda não conectadas</small></footer></div>`;}
function head(k,title,sub,actions=''){return `<div class="page-head"><div><p class="eyebrow">${k}</p><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,value,note,ic='finance'){return `<article class="stat"><div>${label}<span>${icon(ic)}</span></div><strong>${value}</strong><small>${note}</small></article>`;}
const badge=(s)=>`<span class="badge ${s==='Enviado'?'green':s==='Cancelado'?'muted':''}">${esc(s)}</span>`;
function productCell(p){const img=p.images?.[0];return `<div class="product-cell"><div class="thumb">${img?`<img src="${esc(img)}" alt="" loading="lazy">`:`<svg viewBox="0 0 60 60" fill="none"><path d="M20 10l-12 8 7 12 7-4v25h17V26l7 4 7-12-13-8c-3 7-17 7-20 0Z" fill="${p.color==='Branca'?'#e5e6e7':p.color==='Off-white'?'#d3c9b2':'#28354e'}" stroke="#7c8ca7"/><text x="30" y="33" text-anchor="middle" fill="#ddbd71" font-size="7">CW</text></svg>`}</div><div><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.color||'—')} / ${esc(p.size||'—')}</small></div></div>`;}
function orderTable(list){return `<div class="table-wrap"><table><thead><tr><th>Pedido / produto</th><th>Canal</th><th>Quantidade</th><th>Total</th><th>Status</th><th>Ação</th></tr></thead><tbody>${list.map(o=>`<tr><td><strong>${esc(o.id)}</strong><small>${esc(o.name)} · ${new Date(o.date).toLocaleDateString('pt-BR')}</small></td><td>${esc(o.channel)}</td><td>${o.qty}</td><td class="numeric">${money(o.total)}</td><td>${badge(o.status)}</td><td>${o.status==='Reservado'?`<button class="text-btn" data-order="${o.id}" data-status="Enviado">Enviar</button><button class="text-btn muted" data-order="${o.id}" data-status="Cancelado">Cancelar</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum pedido neste filtro.</td></tr>'}</tbody></table></div>`;}
function overview(){const t=totals(state),max=Math.max(1,...channels.map(c=>state.orders.filter(o=>o.channel===c&&o.status!=='Cancelado').reduce((a,o)=>a+o.total,0)));const days=Array.from({length:period},(_,i)=>{const d=new Date();d.setDate(d.getDate()-period+1+i);const val=state.orders.filter(o=>o.status!=='Cancelado'&&new Date(o.date).toDateString()===d.toDateString()).reduce((a,o)=>a+o.total,0);return{date:d.getDate(),val};}),high=Math.max(1,...days.map(d=>d.val)),points=days.map((d,i)=>`${20+i*660/(period-1)},${170-d.val/high*140}`).join(' ');return head('COMMAND CENTER','Sua operação, em movimento.','Estoque, vendas e margem conectados em uma única visão.',button('Simular pedido','new-order',true))+`<section class="hero-strip"><div><span class="live-label"><span class="pulse"></span> CONTROLE CENTRALIZADO</span><h2>Quatro canais.<br><em>Uma fonte de verdade.</em></h2><p>Simule vendas e acompanhe o impacto em toda a operação.</p></div><div class="orb"><div>CW</div><span class="orbit o1">ML</span><span class="orbit o2">S</span><span class="orbit o3">a</span><span class="orbit o4">♪</span></div><div class="hero-summary"><small>ESTOQUE DISPONÍVEL</small><strong>${t.available}<span> peças</span></strong><span class="hero-line"></span><small>${state.products.length} SKUs · 4 canais planejados</small></div></section><section class="stats">${stat('Receita dos pedidos',money(t.total),'Reservados + enviados, sem cancelados')}${stat('Margem de contribuição',money(t.profit),'Após produto, taxas, impostos e logística')}${stat('Pedidos válidos',t.count,`${state.orders.filter(o=>o.status==='Reservado').length} aguardando envio`,'orders')}${stat('Valor em estoque',money(t.inventory),'Custo × estoque físico','stock')}</section><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Receita por dia</h2><p>Atualiza a cada pedido simulado</p></div><div class="segmented">${[7,30].map(n=>`<button data-period="${n}" class="${n===period?'on':''}">${n} dias</button>`).join('')}</div></div><div class="chart"><div class="chart-label">${money(high)}</div><svg viewBox="0 0 700 200" role="img" aria-label="Receita diária dos últimos ${period} dias"><defs><linearGradient id="gold" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#dcb86b" stop-opacity=".3"/><stop offset="1" stop-color="#dcb86b" stop-opacity="0"/></linearGradient></defs>${[30,75,120,170].map(y=>`<path d="M20 ${y}H680" stroke="currentColor" opacity=".1"/>`).join('')}<polygon points="20,170 ${points} 680,170" fill="url(#gold)"/><polyline points="${points}" fill="none" stroke="#dcb86b" stroke-width="3"/>${days.map((d,i)=>i%Math.ceil(period/7)===0||i===period-1?`<text x="${20+i*660/(period-1)}" y="195" fill="currentColor" font-size="11" text-anchor="middle">${d.date}</text>`:'').join('')}</svg></div></section><section class="panel"><div class="panel-head"><div><h2>Vendas por canal</h2><p>Participação na receita simulada</p></div>${icon('channels')}</div><div class="channel-bars">${channels.map((c,i)=>{const v=state.orders.filter(o=>o.channel===c&&o.status!=='Cancelado').reduce((a,o)=>a+o.total,0);return `<div><div><span><b class="channel-symbol c${i}">${['ML','S','a','♪'][i]}</b>${c}</span><strong>${money(v)}</strong></div><div class="bar"><span style="width:${v/max*100}%"></span></div></div>`;}).join('')}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Últimos pedidos</h2><p>Reservas e movimentações em tempo real nesta amostra</p></div><button class="text-btn" data-page="orders">Ver todos →</button></div>${orderTable(state.orders.slice(0,5))}</section>`;}
function catalog(){return head('CATÁLOGO','Produtos que movem o negócio.','Um cadastro central, com variações e adaptações por canal.',button('Novo produto','new-product',true)+button('Importar planilha','go-bulk',false,'bulk'))+`<section class="panel"><div class="panel-head"><h2>${state.products.length} produtos / SKUs</h2><label class="search">${icon('search')}<input id="search" placeholder="Buscar nome ou SKU" value="${esc(filter)}"></label></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Preço base</th><th>Custo</th><th>Disponível</th><th>Cadastro</th><th></th></tr></thead><tbody id="catalog-rows">${catalogRows()}</tbody></table></div></section>`;}
function catalogRows(){return state.products.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(filter.toLowerCase())).map(p=>`<tr><td>${productCell(p)}</td><td>${money(p.price)}<small>${Object.keys(p.channelPrices||{}).length?'Preços por canal configurados':'Preço base para todos os canais'}</small></td><td>${money(p.cost)}</td><td>${available(p)} un.</td><td>${badge(issues(p,channels[0]).length?'Rascunho':'Revisão do canal pendente')}</td><td><button class="text-btn" data-edit="${p.id}">Editar →</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum produto encontrado.</td></tr>';}
function stock(){return head('INVENTÁRIO','Estoque sob controle.','A reserva reduz o disponível. O envio baixa o físico. O cancelamento libera a reserva.')+`<div class="stats">${[['Físico','stock'],['Reservado','reserved'],['Segurança','safety']].map(([n,k])=>stat(n,state.products.reduce((s,p)=>s+p[k],0),'Peças','stock')).join('')}${stat('Disponível',totals(state).available,'Físico − reserva − segurança','stock')}</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Físico</th><th>Reservado</th><th>Segurança</th><th>Disponível</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td>${productCell(p)}</td><td>${p.stock}</td><td>${p.reserved}</td><td>${p.safety}</td><td>${badge(available(p)+' un.')}</td><td><button class="text-btn" data-adjust="${p.id}">Ajustar</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function orders(){return head('FLUXO DE VENDAS','Do pedido ao envio.','Cada pedido guarda seus preços e custos: alterações futuras não reescrevem o histórico.',button('Simular pedido','new-order',true))+`<section class="panel"><div class="panel-head"><h2>Pedidos</h2><select id="order-filter"><option>Todos</option><option>Reservado</option><option>Enviado</option><option>Cancelado</option></select></div><div id="order-list">${orderTable(state.orders)}</div></section>`;}
function finance(){const t=totals(state);return head('FINANCEIRO','Enxergue a margem real.','Resultado gerencial simulado. Custos fixos da empresa e conciliação bancária ainda não incluídos.')+`<div class="stats">${stat('Receita',money(t.total),'Pedidos válidos')}${stat('Custos dos produtos',money(t.cost),'Custo registrado no pedido')}${stat('Taxas + logística',money(t.fees+t.freight),'Condições por canal')}${stat('Contribuição',money(t.profit),'Receita menos custos variáveis')}</div><section class="panel"><div class="panel-head"><h2>Composição do resultado</h2>${badge('Simulação')}</div><div class="waterfall">${[['Receita bruta',t.total],['Produtos',-t.cost],['Comissões e tarifas',-t.fees],['Impostos estimados',-t.tax],['Logística líquida',-t.freight],['Margem de contribuição',t.profit]].map(([n,v])=>`<div><span>${n}</span><strong>${money(v)}</strong></div>`).join('')}</div></section>`;}
const ruleLabels={fee:'Comissão %',fixed:'Tarifa por peça R$',freight:'Frete por peça R$',tax:'Imposto estimado %',margin:'Margem desejada %',programFee:'Adicional do programa %',subsidy:'Subsídio por peça R$',fulfillment:'Fulfillment por peça R$'};
function pricing(){return head('INTELIGÊNCIA DE PREÇO','Sua margem vem primeiro.','Configuração manual por canal. Valores iniciais ilustrativos; confirme os contratos da sua conta.',button('Aplicar preços ao produto','apply-prices',true,'check'))+`<div class="notice">Todos os valores são editáveis. Custos fixos e fretes são considerados por peça nesta amostra. Pedidos antigos preservam o cálculo original.</div><section class="panel pricing-selector"><label>Produto de referência<select id="price-product">${state.products.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.name)} · ${esc(p.sku)} · custo ${money(p.cost)}</option>`).join('')}</select></label></section><div class="price-grid">${channels.map((c,i)=>`<section class="panel price-card"><div class="panel-head"><h2><b class="channel-symbol c${i}">${['ML','S','a','♪'][i]}</b>${c}</h2></div><label>Programa logístico<input data-rule="${c}" data-key="program" value="${esc(draftRules[c].program)}"></label><div class="form-grid">${Object.entries(ruleLabels).map(([k,n])=>`<label>${n}<input type="number" min="0" step="0.01" data-rule="${c}" data-key="${k}" value="${draftRules[c][k]}"></label>`).join('')}</div><div class="quote" data-quote="${c}"></div></section>`).join('')}</div>`;}
function refreshPrices(){const p=state.products.find(p=>p.id===selected);if(!p){document.querySelectorAll('[data-quote]').forEach(el=>el.textContent='Cadastre um produto para simular preços.');return;}document.querySelectorAll('[data-quote]').forEach(el=>{try{const price=quote(p.cost,draftRules[el.dataset.quote]);el.innerHTML=`<small>PREÇO SUGERIDO</small><strong>${money(price)}</strong><span>Atual neste canal: ${money(priceFor(p,el.dataset.quote))}</span>`;}catch(e){el.innerHTML=`<span class="error">${esc(e.message)}</span>`;}});}
function bulk(){return head('CATÁLOGO EM ESCALA','Uma planilha. Toda a operação.','Importe o modelo CentralWork, revise os dados e prepare a fila por canal.',button('Baixar modelo CSV','template',true,'bulk')+button('Exportar catálogo','export',false,'catalog'))+`<div class="notice">Modelo CSV UTF-8, aberto no Excel ou Google Sheets. Uma linha por SKU; use “grupo” para ligar cores e tamanhos. No Excel, importe SKU, GTIN e códigos como texto para preservar zeros iniciais. O arquivo é do CentralWork, não um modelo universal dos marketplaces.</div><section class="panel import-box"><div class="upload-icon">${icon('bulk')}</div><h2>Traga seu catálogo</h2><p>Até 500 variações por importação · CSV · 8 MB</p><label class="btn primary file-label">Escolher planilha<input type="file" id="import-file" accept=".csv,text/csv"></label><small>Imagens por URL HTTPS; múltiplas URLs separadas por |. Upload de imagens também disponível no cadastro.</small></section>${importName?`<section class="panel"><div class="panel-head"><div><h2>${esc(importName)}</h2><p>${imported.length} linhas válidas · ${importErrors.length} erros</p></div>${!importErrors.length&&imported.length?button('Confirmar importação','commit-import',true,'check'):''}</div>${importErrors.length?`<div class="notice error">${importErrors.map(esc).join('<br>')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>SKU</th><th>Produto</th><th>Preço</th><th>Estoque</th><th>Operação</th></tr></thead><tbody>${imported.slice(0,20).map(p=>`<tr><td>${esc(p.sku)}</td><td>${esc(p.name)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td>${state.products.some(x=>x.sku===p.sku)?'Atualizar':'Criar'}</td></tr>`).join('')}</tbody></table></div><p class="pad muted">Prévia limitada às primeiras 20 linhas. A confirmação processa todas as linhas válidas.</p></section>`:''}<section class="panel"><div class="panel-head"><div><h2>Fila de publicação</h2><p>A integração enviará os dados após conectar as APIs e validar as categorias.</p></div>${button('Preparar catálogo','queue',false,'channels')}</div>${queueTable()}</section><section class="panel pad"><h2>Requisitos pesquisados</h2><div class="requirements"><p><strong>Mercado Livre</strong> O importador nativo usa modelo da conta e categoria; não basta replicar esse arquivo nos demais canais. <a href="https://vendedores.mercadolivre.com.br/nota/anuncie-varios-produtos-de-uma-vez-nuevo" target="_blank" rel="noreferrer">Guia oficial ↗</a></p><p><strong>Amazon</strong> Modelos e atributos variam conforme o tipo de produto. <a href="https://venda.amazon.com.br/cadastro-de-produtos" target="_blank" rel="noreferrer">Cadastro oficial ↗</a></p><p><strong>TikTok Shop</strong> O cadastro em massa usa modelos por categoria e linhas por SKU. <a href="https://seller-br.tiktok.com/university/essay?knowledge_id=4339061972092689" target="_blank" rel="noreferrer">Seller Academy ↗</a></p><p><strong>Shopee</strong> O modelo completo e as condições da sua categoria precisam ser conferidos na Central do Vendedor. Conector ainda não implementado.</p></div></section>`;}
function queueTable(){return `<div class="table-wrap"><table><thead><tr><th>SKU</th><th>Canal</th><th>Status</th><th>Pendências básicas</th></tr></thead><tbody>${state.queued.map(q=>{const p=state.products.find(p=>p.id===q.id);if(!p)return'';const pend=issues(p,q.channel);return `<tr><td>${esc(p.sku)}</td><td>${q.channel}</td><td>${badge(pend.length?'Revisar cadastro':'Aguardando API')}</td><td>${esc(pend.join(', ')||'Validação oficial da categoria e autorização pendentes')}</td></tr>`;}).join('')||'<tr><td colspan="4" class="empty">Prepare o catálogo para visualizar as pendências. Nenhum anúncio é publicado nesta amostra.</td></tr>'}</tbody></table></div>`;}
function channelPage(){return head('MULTICANAL','Expanda sem perder o controle.','Consulte o status da sua loja e acompanhe a integração de cada canal.')+`<div class="price-grid">${channels.map((c,i)=>`<section class="panel pad"><h2><b class="channel-symbol c${i}">${['ML','S','a','♪'][i]}</b>${c}</h2>${badge(i===0?'Consultar conexão':'Não conectado')}<p>Catálogo, pedidos, estoque e preços serão sincronizados com autorização da conta.</p><ul><li>Autorização e credenciais no backend</li><li>Regras da categoria e conta</li><li>Webhooks com proteção contra duplicação</li><li>Fila de erros e reprocessamento</li></ul>${i===0?button('Conectar ou ver loja','meli',true,'arrow'):`<button class="btn" data-page="bulk">Revisar catálogo ${icon('arrow')}</button>`}</section>`).join('')}</div>`;}
function plan(){return head('ROADMAP','Da amostra à operação real.','Evolução em etapas, com validação antes de publicar produtos e movimentar estoque.')+`<div class="roadmap">${[['01','Fundação interativa','Disponível na amostra','Cadastro completo, taxas manuais, simulação de pedidos, indicadores, importação CSV e fila de pendências.'],['02','Base operacional','Próxima etapa','Backend com banco de dados, usuários, permissões, mídia persistente, backups e histórico de auditoria.'],['03','Primeiro canal','Após conectar APIs','Integrar Mercado Livre: categorias, validação, anúncio em rascunho, preços, pedidos e sincronização de estoque.'],['04','Operação multicanal','Expansão','Adicionar Shopee, Amazon e TikTok Shop; adaptadores por canal, fila com tentativas, idempotência e conciliação.'],['05','Mobile e automação','Evolução','PWA, notificações push com backend, alertas de estoque, indicadores de campanha e regras logísticas.']].map(([n,t,s,d])=>`<section class="panel roadmap-step"><span>${n}</span><div>${badge(s)}<h2>${t}</h2><p>${d}</p></div>${icon(n==='01'?'check':'arrow')}</section>`).join('')}</div>`;}
function settings(){return head('PREFERÊNCIAS','Seu jeito de operar.','O painel grava os dados compartilhados no Supabase. Use Atualizar do banco para carregar alterações da equipe.')+`<section class="panel pad settings"><h2>Sessão</h2><div class="actions">${button('Atualizar do banco','refresh',false,'check')}${button('Sair','signout',false,'close')}</div><hr><h2>Aparência</h2><label>Tema<select id="theme-select">${[['dark','Escuro'],['light','Claro'],['system','Sistema']].map(([v,n])=>`<option value="${v}" ${state.theme===v?'selected':''}>${n}</option>`).join('')}</select></label><hr><h2>Aplicativo e notificações</h2><p>Instalação depende do navegador. Alertas desta amostra são locais; push com o aplicativo fechado depende de backend.</p><div class="actions">${button('Instalar aplicativo','install',false,'plus')}${button('Testar notificação','notify',false,'bell')}</div><hr><h2>Cópia dos dados</h2><p>Exporte produtos, imagens locais, regras, pedidos e fila em JSON para guardar uma cópia. O catálogo CSV contém apenas URLs públicas de imagens.</p>${button('Baixar backup','backup',false,'bulk')}</section>`;}
function render(){shell();$('#content').innerHTML=({overview,catalog,stock,orders,finance,pricing,bulk,channels:channelPage,plan,settings}[page]||overview)();if(page==='pricing')refreshPrices();}
function go(p){page=p;filter='';if(p==='pricing'){draftRules=structuredClone(state.rules);selected=state.products.some(p=>p.id===selected)?selected:state.products[0]?.id;}render();window.scrollTo(0,0);}
function modal(title,html,wide=false){const d=$('#modal');d.className=wide?'wide':'';d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div>${html}`;d.showModal();}
const field=(n,label,value='',type='text',extra='')=>`<label>${label}<input name="${n}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(n,label,value='')=>`<label class="full">${label}<textarea name="${n}" rows="3">${esc(value)}</textarea></label>`;
function productForm(id){const p=state.products.find(p=>p.id===id)||{cost:0,price:0,stock:0,safety:0,measures:structuredClone(measures),images:[],categories:{},attributes:{}};modal(id?'Editar produto':'Novo produto',`<form id="product-form" data-id="${id||''}" novalidate><p class="notice">O cadastro é um rascunho central. Campos e limites obrigatórios serão validados pela categoria de cada canal.</p><details open><summary>01 · Identificação e variação</summary><div class="form-grid">${field('nome','Nome interno *',p.name)}${field('sku','SKU único *',p.sku)}${field('grupo','Grupo / produto pai',p.group)}${field('titulo','Título do anúncio',p.title)}${field('subtitulo','Subtítulo — uso conforme canal',p.subtitle)}${field('marca','Marca',p.brand)}${field('modelo','Modelo',p.model)}${field('categoria','Categoria interna',p.category)}${field('cor','Cor',p.color)}${field('tamanho','Tamanho',p.size)}${field('gtin','GTIN / EAN — mantenha zeros iniciais',p.gtin)}${field('motivo_sem_gtin','Justificativa sem GTIN — sujeita a aprovação',p.gtinReason)}${field('custo','Custo R$',p.cost,'number','step="0.01" min="0"')}${field('preco','Preço base R$',p.price,'number','step="0.01" min="0"')}${field('estoque','Estoque físico',p.stock,'number','min="0"')}${field('seguranca','Estoque de segurança',p.safety,'number','min="0"')}</div></details><details open><summary>02 · Conteúdo e ficha técnica</summary><div class="form-grid">${area('descricao','Descrição completa',p.description)}${field('material','Material / composição',p.material)}${field('genero','Público / gênero',p.gender)}${area('cuidados','Cuidados e conservação',p.care)}</div></details><details open><summary>03 · Imagens</summary><p class="muted">URLs HTTPS separadas por |. Imagens enviadas aqui ficam neste navegador; futuramente serão hospedadas para os canais.</p>${area('imagens_urls','URLs públicas',p.images.filter(u=>u.startsWith('https://')).join('|'))}<label class="btn file-label">Adicionar imagens locais<input id="product-images" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><small>Até 12 imagens de 2 MB cada. O armazenamento do navegador pode limitar o total.</small><div id="image-preview" class="image-grid">${p.images.map((u,i)=>`<div><img src="${esc(u)}" alt="Imagem ${i+1}"><button type="button" data-remove-image="${i}">Remover</button></div>`).join('')}</div></details><details><summary>04 · Tabela de medidas (cm)</summary><p class="muted">Tabela editável em JSON: tamanho, altura, largura e manga. As medidas padrão são as fornecidas para suas camisetas.</p>${area('medidas_json','Tabela de tamanhos',JSON.stringify(p.measures,null,2))}</details><details><summary>05 · Fiscal e logística</summary><div class="form-grid">${field('peso_kg','Peso embalado (kg)',p.weight||0,'number','step="0.001" min="0"')}${field('comprimento_cm','Comprimento da embalagem (cm)',p.length||0,'number','step="0.1" min="0"')}${field('largura_cm','Largura da embalagem (cm)',p.width||0,'number','step="0.1" min="0"')}${field('altura_cm','Altura da embalagem (cm)',p.height||0,'number','step="0.1" min="0"')}${field('ncm','NCM',p.ncm)}${field('cest','CEST',p.cest)}${field('origem','Origem fiscal',p.origin)}</div></details><details><summary>06 · Atributos por marketplace</summary><div class="form-grid">${channels.map((c,i)=>field(['categoria_ml','categoria_shopee','tipo_amazon','categoria_tiktok'][i],c+' · ID categoria / tipo',p.categories?.[c])).join('')}${area('atributos_json','Atributos adicionais por canal (objeto JSON)',JSON.stringify(p.attributes||{},null,2))}</div><p class="muted">Preços por canal: ${channels.map(c=>c+' '+money(priceFor(p,c)||0)).join(' · ')}. Alterar o preço base limpa os preços específicos; recalcule na aba Precificação.</p></details><p class="error" role="alert" id="form-error"></p><div class="modal-footer"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary" type="submit">Salvar produto ${icon('check')}</button></div></form>`,true);editingImages=structuredClone(p.images);}
let editingImages=[];
function orderForm(){if(!state.products.length)throw Error('Cadastre um produto antes de criar um pedido.');modal('Simular novo pedido',`<form id="order-form"><p class="notice">Simulação local: gera reserva de estoque e atualiza os indicadores.</p><label>Produto<select name="product">${state.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.sku)} · ${available(p)} disponíveis</option>`).join('')}</select></label><div class="form-grid"><label>Canal<select name="channel">${channels.map(c=>`<option>${c}</option>`).join('')}</select></label>${field('qty','Quantidade',1,'number','min="1" step="1"')}</div><div id="order-preview" class="quote"></div><p class="error" role="alert"></p><div class="modal-footer"><button class="btn primary" type="submit">Criar pedido</button></div></form>`);orderPreview();}
function orderPreview(){const f=$('#order-form');if(!f)return;const p=state.products.find(p=>p.id===f.product.value),c=f.channel.value,q=+f.qty.value;if(!p)return;const e=economics(p,c,q,state.rules[c]);$('#order-preview').innerHTML=`<small>TOTAL DO PEDIDO</small><strong>${money(e.total)}</strong><span>Contribuição estimada: ${money(e.profit)}</span>${!Number.isInteger(q)||q<1||q>available(p)?'<p class="error">Quantidade inválida ou estoque insuficiente.</p>':''}`;}
function download(name,content,type='text/plain'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const csvCell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';
function toRow(p){return {sku:p.sku,grupo:p.group,nome:p.name,titulo:p.title,subtitulo:p.subtitle,descricao:p.description,marca:p.brand,modelo:p.model,gtin:p.gtin,motivo_sem_gtin:p.gtinReason,categoria:p.category,cor:p.color,tamanho:p.size,custo:p.cost,preco:p.price,estoque:p.stock,seguranca:p.safety,material:p.material,genero:p.gender,cuidados:p.care,peso_kg:p.weight,comprimento_cm:p.length,largura_cm:p.width,altura_cm:p.height,ncm:p.ncm,cest:p.cest,origem:p.origin,imagens_urls:p.images.filter(u=>u.startsWith('https://')).join('|'),medidas_json:JSON.stringify(p.measures||[]),categoria_ml:p.categories?.[channels[0]],categoria_shopee:p.categories?.[channels[1]],tipo_amazon:p.categories?.[channels[2]],categoria_tiktok:p.categories?.[channels[3]],atributos_json:JSON.stringify(p.attributes||{})};}
function exportCSV(rows,name){download(name,'\uFEFF'+[columns,...rows.map(r=>columns.map(c=>r[c]??''))].map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
async function action(a){if(a==='meli')return openMercadoLivre(modal,esc);if(a==='signout'){authenticated=false;await logout();state=emptyWorkspace();$('#modal').close();showAccess(openWorkspace);return;}if(a==='refresh'){await openWorkspace();return;}if(a==='close')return $('#modal').close();if(a==='menu')return document.body.classList.toggle('menu-open');if(a==='new-product')return productForm();if(a==='new-order')return orderForm();if(a==='go-bulk')return go('bulk');if(a==='theme'){state.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';saveTheme();theme();return;}if(a==='notices')return modal('Notificações · CentralWork',`<div class="pad">${state.notices.map(n=>`<p>${esc(n.text)}<small>${new Date(n.date).toLocaleString('pt-BR')}</small></p>`).join('')||'<p>Sem alertas no momento. As ações da operação aparecerão aqui.</p>'}</div>`);if(a==='apply-prices'){const p=state.products.find(p=>p.id===selected);if(!p)throw Error('Cadastre um produto antes de aplicar preços.');const prices=Object.fromEntries(channels.map(c=>[c,quote(p.cost,draftRules[c])]));p.channelPrices=prices;state.rules=structuredClone(draftRules);notice('Regras e preços atualizados para '+p.name);await persist();render();toast('Preços aplicados aos quatro canais da simulação.');return;}if(a==='template'){const p={...seed().products[0],sku:'EXEMPLO-PT-M',name:'SUBSTITUA ESTE EXEMPLO',title:'Camiseta exemplo',stock:20};exportCSV([toRow(p)],'CentralWork_Modelo.csv');return;}if(a==='export')return exportCSV(state.products.map(toRow),'CentralWork_Catalogo.csv');if(a==='backup')return download('CentralWork_Backup.json',JSON.stringify(state,null,2),'application/json');if(a==='queue'){state.queued=state.products.flatMap(p=>channels.map(channel=>({id:p.id,channel})));notice('Fila preparada; aguardando revisão e APIs.');await persist();render();return;}if(a==='commit-import'){if(importErrors.length||!imported.length)return;for(const p of imported){const old=state.products.find(x=>x.sku===p.sku);if(old){if(p.stock<old.reserved+p.safety)throw Error('Reservas mudaram. Importe novamente.');Object.assign(old,p,{reserved:old.reserved,id:old.id});}else state.products.push(p);}notice(imported.length+' produtos importados.');await persist();imported=[];importName='';render();toast('Catálogo importado. Prepare a fila para revisar os canais.');return;}if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else modal('Instalar CentralWork','<div class="pad"><p>No Android/Chrome: menu do navegador → Instalar aplicativo ou Adicionar à tela inicial.</p><p>No iPhone/Safari: Compartilhar → Adicionar à Tela de Início.</p><p>A disponibilidade depende do navegador e do acesso ao site.</p></div>');return;}if(a==='notify'){if(!('Notification'in window))throw Error('Este navegador não oferece notificações.');const p=await Notification.requestPermission();if(p!=='granted')throw Error('Permissão de notificação não concedida.');const r=await navigator.serviceWorker?.getRegistration();if(r)await r.showNotification('CentralWork',{body:'Teste local: sua central de operação está pronta.',icon:'./icon-192.png'});else new Notification('CentralWork',{body:'Teste de notificação local.'});}}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-page]');if(!b||!authenticated||saving)return;const before=structuredClone(state);try{if(b.dataset.page){document.body.classList.remove('menu-open');go(b.dataset.page);}else if(b.dataset.period){period=+b.dataset.period;render();}else if(b.dataset.edit)productForm(b.dataset.edit);else if(b.dataset.adjust){const p=state.products.find(p=>p.id===b.dataset.adjust);modal('Ajustar estoque',`<form id="adjust-form" data-id="${p.id}"><p>${esc(p.name)} · ${p.reserved} reservados</p>${field('stock','Novo estoque físico',p.stock,'number','min="0" step="1"')}${field('safety','Estoque de segurança',p.safety,'number','min="0" step="1"')}<p role="alert" class="error"></p><div class="modal-footer"><button type="submit" class="btn primary">Salvar ajuste</button></div></form>`);}else if(b.dataset.order){transition(state,b.dataset.order,b.dataset.status);notice(b.dataset.order+' · '+b.dataset.status);await persist();render();toast('Estoque e indicadores atualizados.');}else if(b.dataset.removeImage!==undefined){const removed=editingImages.splice(+b.dataset.removeImage,1)[0];const urls=$('[name="imagens_urls"]');if(urls&&removed?.startsWith('https://'))urls.value=urls.value.split('|').map(x=>x.trim()).filter(x=>x!==removed).join('|');imagePreview();}else if(b.dataset.action)await action(b.dataset.action);}catch(err){state=before;toast(err.name==='QuotaExceededError'?'Armazenamento cheio. Exporte um backup e reduza as imagens.':err.message);}});
function imagePreview(){$('#image-preview').innerHTML=editingImages.map((u,i)=>`<div><img src="${esc(u)}" alt="Imagem ${i+1}"><button type="button" data-remove-image="${i}">Remover</button></div>`).join('');}
document.addEventListener('submit',async e=>{if(!authenticated)return;e.preventDefault();if(saving)return;const f=e.target,before=structuredClone(state);try{if(f.id==='product-form'){const r=Object.fromEntries(new FormData(f)),old=state.products.find(p=>p.id===f.dataset.id);if(state.products.some(p=>p.sku===r.sku.trim()&&p.id!==old?.id))throw Error('SKU já cadastrado.');const p=importProduct(r,old);p.images=[...new Set([...editingImages.filter(u=>u.startsWith('data:image/')),...p.images])];if(p.images.length>12)throw Error('Limite de 12 imagens por SKU nesta amostra.');if(old)Object.assign(old,p);else state.products.push(p);notice('Produto salvo: '+p.name);}else if(f.id==='order-form'){const o=addOrder(state,f.product.value,f.channel.value,+f.qty.value);notice('Pedido '+o.id+' reservado.');}else if(f.id==='adjust-form'){const p=state.products.find(p=>p.id===f.dataset.id),stock=+f.stock.value,safety=+f.safety.value;if(!Number.isInteger(stock)||!Number.isInteger(safety)||stock<0||safety<0||stock<p.reserved+safety)throw Error('Estoque deve cobrir reservas + segurança.');p.stock=stock;p.safety=safety;notice('Estoque ajustado: '+p.sku);}else return;await persist();$('#modal').close();render();toast('Salvo. Indicadores atualizados.');}catch(err){state=before;const alert=f.querySelector('[role="alert"]');if(alert)alert.textContent=err.name==='QuotaExceededError'?'Armazenamento cheio. Reduza as imagens ou use URLs públicas.':err.message;}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){filter=t.value;$('#catalog-rows').innerHTML=catalogRows();}if(t.dataset.rule){draftRules[t.dataset.rule][t.dataset.key]=t.dataset.key==='program'?t.value:t.value===''?NaN:+t.value;refreshPrices();}if(t.closest('#order-form'))orderPreview();});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='price-product'){selected=t.value;refreshPrices();}if(t.id==='order-filter')$('#order-list').innerHTML=orderTable(state.orders.filter(o=>t.value==='Todos'||o.status===t.value));if(t.id==='theme-select'){state.theme=t.value;saveTheme();theme();}if(t.closest('#order-form'))orderPreview();if(t.id==='product-images'){if(editingImages.length+t.files.length>12)throw Error('Máximo de 12 imagens.');const added=[];for(const f of t.files){if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>2*1024*1024)throw Error('Use JPG, PNG ou WebP de até 2 MB.');added.push(await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result);r.onerror=no;r.readAsDataURL(f);}));}editingImages.push(...added);imagePreview();}if(t.id==='import-file'){const f=t.files[0];if(!f)return;importName=f.name;imported=[];importErrors=[];if(f.size>8*1024*1024)throw Error('Arquivo excede 8 MB.');const rows=parseCSV(await f.text());if(rows.length>500)throw Error('Limite de 500 linhas por importação.');const seen=new Set();rows.forEach((r,i)=>{try{if(seen.has(r.sku?.trim()))throw Error('SKU repetido no arquivo.');seen.add(r.sku?.trim());imported.push(importProduct(r,state.products.find(p=>p.sku===r.sku?.trim())));}catch(err){importErrors.push('Linha '+(i+2)+': '+err.message);}});render();}}catch(err){if(t.id==='import-file'){importErrors.push(err.message);render();}toast(err.message);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(state.theme==='system')theme();});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
async function openWorkspace() {
  const row = await loadWorkspace();
  if (!Number.isSafeInteger(row.revision)) throw new Error('Revisão inválida no banco.');
  const data = row.data;
  const themePreference = localStorage.getItem('centralwork-theme');
  state = data.version === 4 ? data : emptyWorkspace();
  state.theme = ['dark','light','system'].includes(themePreference) ? themePreference : 'dark';
  revision = row.revision;
  authenticated = true;
  go('overview');
}
const resultUrl = new URL(location.href);
const mercadoLivreResult = resultUrl.searchParams.get('mercado_livre');
if (mercadoLivreResult) {
  resultUrl.searchParams.delete('mercado_livre');
  history.replaceState(null, '', resultUrl.pathname + resultUrl.search + resultUrl.hash);
}
showAccess(async () => {
  await openWorkspace();
  if (!mercadoLivreResult) return;
  go('channels');
  const messages = new Map([
    ['conectado', 'Mercado Livre conectado.'],
    ['outra_loja', 'A conta autorizada é diferente da loja já conectada.'],
    ['erro', 'Autorização incompleta. Confira o Redirect URI e tente novamente.']
  ]);
  toast(messages.get(mercadoLivreResult) ?? 'Consulte o estado da conexão.');
});
